fn cmd(name:&str,argv:Vec<String>,env:Value)->Value{json!({"kind":"command","name":name,"argv":argv,"environment":env,"timeout_seconds":1800})}
fn prepare(){assert!(!r("plan.json").exists());let parent="/home/ubuntu/src/zopro-perf-work/g1-offset177";let ids=read(format!("{parent}/runtime-consumers.json"));check_copies();let prior_jobs=read(format!("{parent}/main-jobs.json"));let job=prior_jobs.as_array().unwrap().iter().find(|j|j["case"]["name"]=="1x2-w32").unwrap();let case=job["case"].clone();let base=job["environment"].clone();let mut jobs=vec![];let mut steps=vec![];
 for dir in["stat","perf"]{fs::create_dir(r(dir)).unwrap();}for f in["ctl","ack"]{assert!(Command::new("mkfifo").args(["-m","600"]).arg(r(f)).status().unwrap().success());}
 for block in 0..3{let mut panels=vec!["plain","stat","cycles"];panels.rotate_left(block);let mut arms=vec!["OFF","ON"];if block%2==1{panels.reverse();arms.reverse();}for panel in panels{for arm in &arms{let name=format!("{panel}-{arm}-{block}");let binary=ids[*arm]["copies"][block]["path"].as_str().unwrap();assert_eq!(hash(binary),ids[*arm]["sha256"]);let mut env=base.clone();let mut argv=vec![];let mut data=Value::Null;
 if panel!="plain"{env["ZOPRO_BENCH_PERF_CTL"]=json!(r("ctl"));env["ZOPRO_BENCH_PERF_ACK"]=json!(r("ack"));argv.extend(["sudo".into(),"-n".into(),"env".into()]);for(k,v)in env.as_object().unwrap(){argv.push(format!("{k}={}",v.as_str().unwrap()));}argv.push("perf".into());if panel=="stat"{let p=r(format!("stat/{name}.csv"));data=json!(p);argv.extend(["stat".into(),"--no-big-num".into(),"-x".into(),";".into(),"-e".into(),"{cycles:u,instructions:u,cache-misses:u,branch-misses:u}".into(),"-o".into(),p.display().to_string()]);}else{let p=r(format!("perf/{name}.data"));data=json!(p);argv.extend(["record".into(),"--no-buildid-cache".into(),"--sample-cpu".into(),"--timestamp".into(),"-P".into(),"-e".into(),"cycles:u".into(),"-c".into(),"16000000".into(),"-m".into(),"512".into(),"-o".into(),p.display().to_string()]);}argv.extend(["--delay=-1".into(),format!("--control=fifo:{},{}",r("ctl").display(),r("ack").display()),"--".into()]);}
 let dir=r(format!("proofs/{name}"));argv.extend(["/usr/bin/taskset".into(),"-c".into(),"0-31".into(),binary.into(),case["image"].as_str().unwrap().into(),case["request"].as_str().unwrap().into(),"251".into(),dir.display().to_string()]);steps.push(cmd(&name,argv,if panel=="plain"{env.clone()}else{json!({})}));jobs.push(json!({"name":name,"case":case,"arm":arm,"block":block,"panel":panel,"rounds":251,"binary":binary,"proof_dir":dir,"data":data,"environment":env}));}}}
 assert_eq!(jobs.len(),18);
 for j in jobs.iter().filter(|j|j["panel"]=="cycles"){let name=j["name"].as_str().unwrap();let p=j["data"].as_str().unwrap();steps.push(cmd(&format!("own-{name}"),vec!["sudo".into(),"-n".into(),"chown".into(),"ubuntu:ubuntu".into(),p.into()],json!({})));for(label,args)in[("events",vec!["perf","evlist","-v","-i",p]),("decode",vec!["perf","script","--ns","-i",p,"-F","pid,tid,cpu,time,period,ip,sym"]),("metadata",vec!["perf","script","--header","--show-mmap-events","--show-task-events","--ns","-i",p,"-F","pid,tid,cpu,time,period,ip,sym"])]{steps.push(cmd(&format!("{label}-{name}"),args.into_iter().map(str::to_owned).collect(),json!({})));}steps.push(cmd(&format!("loss-{name}"),vec![r("profile").display().to_string(),"loss".into(),p.into()],json!({})));}
 for j in &jobs{let d=j["proof_dir"].as_str().unwrap();steps.push(cmd(&format!("verify-{}",j["name"].as_str().unwrap()),vec![VERIFY.into(),case["image"].as_str().unwrap().into(),case["image_sha256"].as_str().unwrap().into(),format!("{d}/0.proof"),format!("{d}/0.public"),case["public_sha256"].as_str().unwrap().into()],json!({})));}
 save("jobs.json",&json!(jobs));let mut pins=BTreeMap::new();for arm in["OFF","ON"]{for f in ids[arm]["copies"].as_array().unwrap(){let p=f["path"].as_str().unwrap();pins.insert(p.into(),hash(p));}}pins.insert(format!("{parent}/runtime-consumers.json"),hash(format!("{parent}/runtime-consumers.json")));for f in["protocol.md","profile.rs","profile","common.rs","sampling.rs","metadata.rs","counter.rs","jobs.json"]{pins.insert(r(f).display().to_string(),hash(r(f)));}for p in[SEED,VERIFY,"/usr/bin/perf","/usr/bin/taskset","/usr/bin/sudo",ids["OFF"]["path"].as_str().unwrap(),ids["ON"]["path"].as_str().unwrap(),case["image"].as_str().unwrap(),case["request"].as_str().unwrap()]{pins.insert(p.into(),hash(p));}assert_eq!(hash(case["image"].as_str().unwrap()),case["image_sha256"]);assert_eq!(read(SEED).as_array().unwrap().len(),52927);save("pins.json",&json!(pins));save("plan.json",&json!({"version":1,"source_pins":r("pins.json"),"steps":steps}));println!("Frozen18diagnosticprocesses/4572SDKcalls/18exports; sixprofiles, sixcounters, sixplain controls");}
fn loss(p:&str){assert!(Path::new(p).starts_with(r("perf")));let mut child=Command::new("perf").args(["script","-D","-i",p]).stdout(Stdio::piped()).spawn().unwrap();let mut lost=vec![];let mut lines=0;for l in BufReader::new(child.stdout.take().unwrap()).lines(){let l=l.unwrap();lines+=1;if l.contains("PERF_RECORD_LOST"){lost.push(l);}}assert!(child.wait().unwrap().success());println!("{}",json!({"zero_lost":lost.is_empty(),"lost":lost,"decoded_lines":lines}));}
